(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,94467,e=>{"use strict";var t=e.i(79082);let o=[{id:"btl-01",mode:"standard",category:"bottleneck",subskill:"throughput constraint",industry:"Dental practice",difficulty:1,scenario:"Your practice gets 60 new-patient calls a month. With your current hygienists, you can only schedule 22 of them. The rest go elsewhere.",prompt:"Where should you focus first?",choices:[{id:"a",text:"Increase the advertising budget"},{id:"b",text:"Add hygienist chair capacity"},{id:"c",text:"Redesign the practice website"},{id:"d",text:"Launch a patient referral program"}],correctChoiceId:"b",explanation:"You already generate more demand than you can serve. Until chair capacity rises, every additional call is wasted money."},{id:"btl-02",mode:"standard",category:"bottleneck",subskill:"throughput constraint",industry:"E-commerce",difficulty:1,scenario:"Your warehouse ships 200 orders a day. You are currently receiving 340 orders a day, and the unshipped backlog grows every day.",prompt:"What is the constraint?",choices:[{id:"a",text:"Website conversion rate"},{id:"b",text:"Advertising spend"},{id:"c",text:"Pick-and-pack capacity"},{id:"d",text:"Product selection"}],correctChoiceId:"c",explanation:"Demand exceeds fulfillment by 140 orders a day. Fulfillment is the ceiling on the entire business right now."},{id:"btl-03",mode:"standard",category:"bottleneck",subskill:"idle capacity",industry:"Design agency",difficulty:2,scenario:"You have four designers. Each comfortably handles five projects a month. You currently have 11 active projects and next month's pipeline is thin.",prompt:"What is the best next move?",choices:[{id:"a",text:"Hire a fifth designer"},{id:"b",text:"Invest in generating more qualified demand"},{id:"c",text:"Buy faster design software"},{id:"d",text:"Extend project timelines so the team looks fully booked"}],correctChoiceId:"b",explanation:"Capacity is 20 projects and you are using 11. The constraint is demand, not delivery, so adding a designer only adds cost and idle time."},{id:"btl-04",mode:"standard",category:"bottleneck",subskill:"sequential capacity",industry:"Coffee roastery",difficulty:2,scenario:"Your roaster runs eight hours a day and produces 400 lb. Your packaging line can handle 700 lb a day. Orders average 520 lb a day.",prompt:"What limits how much you can ship?",choices:[{id:"a",text:"Roasting hours"},{id:"b",text:"Packaging speed"},{id:"c",text:"Order volume"},{id:"d",text:"Green bean inventory"}],correctChoiceId:"a",explanation:"In a sequence, output is set by the slowest step. Roasting caps you at 400 lb, well below both packaging capacity and demand."},{id:"btl-05",mode:"standard",category:"bottleneck",subskill:"reading operating data",industry:"Freight brokerage",difficulty:3,scenario:"Two months of operating data:",data:{columns:["","Last month","This month"],rows:[{label:"Loads quoted",values:["1,200","1,650"]},{label:"Loads booked",values:["310","425"]},{label:"Loads covered with a carrier",values:["305","342"]},{label:"Loads delivered on time",values:["291","300"]}],note:"Customer complaints about late pickups are rising."},prompt:"Where should management focus?",choices:[{id:"a",text:"Quoting volume"},{id:"b",text:"Sales conversion"},{id:"c",text:"Carrier capacity and coverage"},{id:"d",text:"Pricing"}],correctChoiceId:"c",explanation:"Bookings grew 37% but coverage grew only 12%, and the gap between booked and covered widened from 5 loads to 83. The break is in sourcing carriers."},{id:"btl-06",mode:"standard",category:"bottleneck",subskill:"reading operating data",industry:"B2B SaaS support",difficulty:3,scenario:"Your support desk over the last four weeks:",data:{columns:["","Wk 1","Wk 2","Wk 3","Wk 4"],rows:[{label:"Tickets opened",values:["420","445","460","470"]},{label:"Tickets closed",values:["415","430","405","390"]},{label:"Support headcount",values:["6","6","6","6"]},{label:"Avg handle time (min)",values:["14","15","19","23"]}]},prompt:"What is the most useful thing to investigate?",choices:[{id:"a",text:"Why handle time per ticket is climbing"},{id:"b",text:"Why customers are opening more tickets"},{id:"c",text:"Whether to hire two more support reps"},{id:"d",text:"Whether to raise prices to reduce demand"}],correctChoiceId:"a",explanation:"Volume rose 12% but closures fell 6% while handle time rose 64%. Something changed inside the work itself, and hiring against a broken process just buys the same problem twice."},{id:"btl-07",mode:"standard",category:"bottleneck",subskill:"investing off the constraint",industry:"Furniture manufacturing",difficulty:4,scenario:"Your line has three stations. Cutting takes 40 seconds per unit, assembly takes 95 seconds, and finishing takes 55 seconds. A vendor offers a machine that would cut the cutting station to 20 seconds.",prompt:"What would that purchase do to daily output?",choices:[{id:"a",text:"Roughly double it, since cutting becomes twice as fast"},{id:"b",text:"Increase it by about 40%"},{id:"c",text:"Leave it essentially unchanged"},{id:"d",text:"Decrease it, because of retraining time"}],correctChoiceId:"c",explanation:"Assembly at 95 seconds sets the pace of the line. Speeding up a non-bottleneck only piles up inventory in front of assembly; it does not add a single finished unit."},{id:"btl-08",mode:"standard",category:"bottleneck",subskill:"constraint behind a symptom",industry:"Fitness studio",difficulty:4,scenario:"Membership sales are strong at 90 joins last month, but you also lost 84 members. Your 6pm classes have been fully booked with waitlists for three months. Off-peak classes run at 30% capacity.",prompt:"What is the highest-leverage move?",choices:[{id:"a",text:"Increase the marketing budget to outrun churn"},{id:"b",text:"Add capacity or attractive alternatives at peak hours"},{id:"c",text:"Discount memberships to improve retention"},{id:"d",text:"Cut the underused off-peak classes to save money"}],correctChoiceId:"b",explanation:"You are selling memberships to people who cannot get into the class they actually want. Peak capacity is producing the churn, so more marketing only fills a leaking bucket faster."},{id:"btl-09",mode:"standard",category:"bottleneck",subskill:"the constraint moves",industry:"Imaging clinic",difficulty:5,scenario:"Referrals are up 25%. You added a second MRI machine last quarter and scanner utilization fell from 96% to 61%. Radiologist read turnaround has gone from 1 day to 4 days, and referring physicians are starting to send patients elsewhere.",prompt:"What should you do?",choices:[{id:"a",text:"Market harder to referring physicians to replace lost volume"},{id:"b",text:"Add radiologist reading capacity"},{id:"c",text:"Add a third scanner to shorten appointment lead times"},{id:"d",text:"Reduce referral intake until turnaround normalizes"}],correctChoiceId:"b",explanation:"The second scanner worked, and in working it pushed the constraint downstream. Reads are now the ceiling, and turnaround is the part referring physicians actually experience."},{id:"btl-10",mode:"standard",category:"bottleneck",subskill:"constraint is not capacity",industry:"Specialty contractor",difficulty:5,scenario:"Crews are only 60% utilized and you have $900,000 of signed work. Jobs stall because materials arrive late: your main supplier requires payment before shipping, and your customers pay 45 days after completion.",prompt:"What is actually constraining the business?",choices:[{id:"a",text:"Crew productivity"},{id:"b",text:"Sales volume"},{id:"c",text:"Working capital and payment timing"},{id:"d",text:"Supplier reliability"}],correctChoiceId:"c",explanation:"You pay for materials up front and collect 45 days after finishing. Cash, not labor or demand, is what caps how many jobs you can run at once."},{id:"btl-11",mode:"standard",category:"bottleneck",subskill:"diagnosis before investment",industry:"Restaurant group",difficulty:6,scenario:"Across six locations, average ticket times went from 12 to 19 minutes over four months. Two locations are unchanged. Sales are flat, food cost is stable, and kitchen headcount has not changed. A consultant recommends a $240,000 equipment upgrade across all six.",prompt:"What should you do first?",choices:[{id:"a",text:"Approve the upgrade, since ticket times are clearly a capacity problem"},{id:"b",text:"Upgrade only the four affected locations to save money"},{id:"c",text:"Find out what is different about the two unaffected locations"},{id:"d",text:"Add a cook to every affected location"}],correctChoiceId:"c",explanation:"Same equipment and same staffing produced different results, so equipment is unlikely to be the cause. The two healthy locations are a free control group, and the real answer is probably far cheaper than $240,000."},{id:"btl-12",mode:"standard",category:"bottleneck",subskill:"shifting constraints",industry:"Metal fabrication",difficulty:6,scenario:"Your shop's bottleneck changes by job type. Bracket work backs up at welding; enclosure work backs up at powder coating. Each accounts for roughly half your revenue. You have budget to expand exactly one of the two.",prompt:"What is the strongest basis for the decision?",choices:[{id:"a",text:"Expand welding, since welders are harder to hire"},{id:"b",text:"Expand whichever station has more idle hours overall"},{id:"c",text:"Expand whichever constraint blocks more contribution margin per hour"},{id:"d",text:"Split the budget evenly to keep both moving"}],correctChoiceId:"c",explanation:"With alternating constraints, the tiebreaker is money released per constrained hour, not hiring difficulty or fairness. Splitting the budget buys too little relief at either station to change throughput."}],i=[{id:"fin-01",mode:"standard",category:"financial",subskill:"unit economics",industry:"Meal delivery",difficulty:1,scenario:"Each meal box sells for $50. Food, packaging and delivery cost you $58 per box. Orders are growing quickly.",prompt:"What should you do?",choices:[{id:"a",text:"Push for more volume to spread costs"},{id:"b",text:"Fix the price or the cost before growing further"},{id:"c",text:"Raise the marketing budget to accelerate growth"},{id:"d",text:"Add more menu options to increase order size"}],correctChoiceId:"b",work:["Contribution per box = $50 selling price − $58 variable cost = −$8.","At 100 more orders, that loss grows by another $800 before fixed costs.","Make one order profitable first; only then does added volume help."],explanation:"You lose $8 on every box. Volume multiplies a loss rather than curing it, so the economics have to work on one unit first."},{id:"fin-02",mode:"standard",category:"financial",subskill:"profit versus cash",industry:"Wholesale distribution",difficulty:1,scenario:"Your P&L shows $80,000 of profit last quarter, but your bank balance fell. All of your customers pay on 60-day terms and sales grew 40%.",prompt:"What is the most likely explanation?",choices:[{id:"a",text:"The P&L is wrong"},{id:"b",text:"Growth tied up cash in unpaid invoices"},{id:"c",text:"Your margins are negative"},{id:"d",text:"Someone is stealing from the business"}],correctChoiceId:"b",work:["The P&L records revenue when customers are invoiced, not when they pay.","With 60-day terms, the newest sales can sit in receivables for two months.","Forty-percent growth therefore creates a larger cash gap even while reported profit rises."],explanation:"Profit is recorded when you invoice; cash arrives 60 days later. Fast growth means you fund more inventory and receivables before collecting, so a profitable quarter can still drain the bank."},{id:"fin-03",mode:"standard",category:"financial",subskill:"gross margin",industry:"Furniture retail",difficulty:2,scenario:"A chair sells for $400. It costs $260 landed. Your salesperson wants to discount it to $340 to close a hesitant customer.",prompt:"What does that discount do?",choices:[{id:"a",text:"Cuts gross profit from $140 to $80, a 43% reduction"},{id:"b",text:"Cuts gross profit by 15%, matching the discount"},{id:"c",text:"Leaves gross profit roughly unchanged"},{id:"d",text:"Turns the sale into a loss"}],correctChoiceId:"a",work:["Original gross profit = $400 − $260 = $140.","Discounted gross profit = $340 − $260 = $80.","Profit lost = $60 ÷ $140 = 42.9%, even though price fell only 15%."],explanation:"The discount comes entirely out of profit, not cost. A 15% price cut removed 43% of the gross profit on that chair."},{id:"fin-04",mode:"standard",category:"financial",subskill:"discount and volume",industry:"Industrial supply",difficulty:2,scenario:"Your gross margin is 30%. A customer asks for a 10% discount and promises more volume.",prompt:"Roughly how much more volume do you need just to break even on the deal?",choices:[{id:"a",text:"About 10% more"},{id:"b",text:"About 33% more"},{id:"c",text:"About 50% more"},{id:"d",text:"About 15% more"}],correctChoiceId:"c",work:["Start with $100 of sales: a 30% margin produces $30 of gross profit.","After a 10% discount, revenue is $90 while the $70 cost is unchanged, leaving $20.","Required volume = $30 ÷ $20 = 1.5, so volume must rise 50% just to stand still."],explanation:"The discount takes margin from 30 points to 20. To earn the same total gross profit you need 30/20, or 50% more volume — which is why blanket discounts are so expensive."},{id:"fin-05",mode:"standard",category:"financial",subskill:"reading a P&L",industry:"Building products",difficulty:3,scenario:"Year-over-year results:",data:{columns:["","Last year","This year"],rows:[{label:"Revenue",values:["$4.0M","$5.0M"]},{label:"Gross margin",values:["38%","38%"]},{label:"Operating expenses",values:["$1.24M","$1.72M"]},{label:"Net profit",values:["$280,000","$180,000"]}]},prompt:"What should you investigate?",choices:[{id:"a",text:"Pricing, since margin should have improved with scale"},{id:"b",text:"Sales, since revenue growth was too slow"},{id:"c",text:"Operating expenses, which grew faster than revenue"},{id:"d",text:"Cost of goods, which must have crept up"}],correctChoiceId:"c",work:["Revenue growth = ($5.0M − $4.0M) ÷ $4.0M = 25%.","Operating-expense growth = ($1.72M − $1.24M) ÷ $1.24M ≈ 38.7%.","Gross margin held at 38%, so overhead growing 14 points faster than revenue is the outlier."],explanation:"Revenue rose 25% and gross margin held, so the product economics are intact. Overhead rose 39%, which is the entire reason profit fell."},{id:"fin-06",mode:"standard",category:"financial",subskill:"payback period",industry:"Subscription software",difficulty:3,scenario:"It costs $900 to acquire a customer. Each customer pays $100 a month at 80% gross margin and stays about 30 months. Your cash reserves cover roughly four months of operating expenses.",prompt:"What is the most important number here?",choices:[{id:"a",text:"Lifetime value of $2,400, which comfortably exceeds $900"},{id:"b",text:"The 11-month payback period against four months of runway"},{id:"c",text:"The 80% gross margin"},{id:"d",text:"The 30-month average customer life"}],correctChoiceId:"b",work:["Monthly gross profit per customer = $100 × 80% = $80.","CAC payback = $900 ÷ $80 = 11.25 months.","The company has only four months of runway, so it cannot wait eleven months to recycle each acquisition dollar."],explanation:"The lifetime value is healthy, but you spend $900 today and recover it at $80 a month — 11 months. With four months of reserves, growth speed is limited by cash, not by whether the customer is profitable."},{id:"fin-07",mode:"standard",category:"financial",subskill:"cash conversion cycle",industry:"Apparel brand",difficulty:4,scenario:"You pay factories 100% up front. Goods take 60 days to arrive, sit in the warehouse about 45 days, and wholesale customers pay 60 days after delivery. The business is profitable and orders are doubling.",prompt:"What is the first thing to change?",choices:[{id:"a",text:"Raise prices to improve margin"},{id:"b",text:"Attack the 165-day gap between paying and getting paid"},{id:"c",text:"Cut marketing to preserve cash"},{id:"d",text:"Slow growth until margins improve"}],correctChoiceId:"b",work:["Cash leaves when the factory is paid, then goods spend 60 days in transit.","Add 45 warehouse days and 60 customer-payment days.","Total cash gap = 60 + 45 + 60 = 165 days."],explanation:"You fund every order for about 165 days, so doubling orders doubles the cash you must front. Supplier terms, faster turns, or customer deposits fix the actual problem; better margin on a 165-day cycle still starves you."},{id:"fin-08",mode:"standard",category:"financial",subskill:"breakeven and fixed cost",industry:"Fitness franchise",difficulty:4,scenario:"Fixed costs are $42,000 a month. Each membership brings $120 a month with $20 of variable cost. You currently have 380 members and are considering a second studio with the same cost structure.",prompt:"What does the math say?",choices:[{id:"a",text:"You clear breakeven at 380 members, so the model is proven"},{id:"b",text:"You are about $4,000 a month short of breakeven"},{id:"c",text:"You are exactly at breakeven"},{id:"d",text:"Breakeven cannot be determined from this information"}],correctChoiceId:"b",work:["Contribution per membership = $120 price − $20 variable cost = $100.","Current contribution = 380 × $100 = $38,000 per month.","$42,000 fixed cost − $38,000 contribution = a $4,000 monthly shortfall; breakeven is 420 members."],explanation:"Contribution is $100 per member, so 380 members produce $38,000 against $42,000 of fixed cost and breakeven is 420. Opening a second studio on the same cost structure would duplicate a unit that does not yet cover itself."},{id:"fin-09",mode:"standard",category:"financial",subskill:"contribution margin on idle capacity",industry:"Commercial bakery",difficulty:5,scenario:"Your ovens sit idle overnight. A grocery chain offers a standing order at $2.10 per loaf. Your fully loaded cost is $2.40, of which $1.55 is ingredients and direct labor and $0.85 is allocated overhead. Your daytime retail business is unaffected and stays full.",prompt:"Should you take the order?",choices:[{id:"a",text:"No — $2.10 is below the $2.40 cost"},{id:"b",text:"Yes — it adds $0.55 per loaf against otherwise idle capacity"},{id:"c",text:"Only if they raise the price above $2.40"},{id:"d",text:"Yes, but only if you cut ingredient quality to reach the price"}],correctChoiceId:"b",work:["The $0.85 allocated overhead is already being paid while the ovens sit idle.","Incremental contribution = $2.10 price − $1.55 ingredients and direct labor = $0.55 per loaf.","Because existing retail sales are unaffected, every accepted loaf adds $0.55 toward profit."],explanation:"The $0.85 of overhead is paid whether the ovens run or not. Against genuinely idle capacity the relevant comparison is the $1.55 of incremental cost, so each loaf contributes $0.55 you would not otherwise have."},{id:"fin-10",mode:"standard",category:"financial",subskill:"cost of capital in plain terms",industry:"Auto parts distributor",difficulty:5,scenario:"A supplier offers 2% off if you pay in 10 days instead of the standard 30. You have a line of credit costing 12% a year and are not otherwise short on cash.",prompt:"What should you do?",choices:[{id:"a",text:"Skip it — 2% is too small to matter"},{id:"b",text:"Take the discount, even if you have to draw on the credit line"},{id:"c",text:"Take it only when you have surplus cash on hand"},{id:"d",text:"Negotiate for 45-day terms instead"}],correctChoiceId:"b",work:["Paying 20 days early earns 2%, or roughly 2% × (365 ÷ 20) = 36.5% annualized.","Financing those 20 days at 12% costs about 12% × (20 ÷ 365) = 0.66%.","The 2% discount comfortably exceeds the 0.66% borrowing cost."],explanation:"You earn 2% for paying 20 days early, which annualizes to roughly 36%. Borrowing at 12% to capture a 36% return is worth doing on every invoice."},{id:"fin-11",mode:"standard",category:"financial",subskill:"cost to serve",industry:"Managed IT services",difficulty:6,scenario:"Your enterprise segment produces the highest revenue per client and the highest gross margin on paper. It also absorbs about 70% of engineering escalations and your two most senior engineers, whose time is booked to a shared overhead pool rather than to clients.",prompt:"What is the right conclusion?",choices:[{id:"a",text:"Enterprise is your best segment; sell more of it"},{id:"b",text:"The reported margin may be wrong because cost to serve is hidden in overhead"},{id:"c",text:"Escalations are a support problem, not a financial one"},{id:"d",text:"Raise small-business prices to subsidize enterprise"}],correctChoiceId:"b",work:["Reported segment margin excludes senior-engineering time because that time sits in shared overhead.","Enterprise consumes 70% of escalations plus the two most expensive engineers.","Reassign those service costs to the clients causing them, then compare true contribution by segment."],explanation:"When the largest cost of serving a segment sits in a shared pool, that segment always looks best. Assign senior engineering time to the accounts consuming it before deciding where to grow."},{id:"fin-12",mode:"standard",category:"financial",subskill:"cutting cost that produces revenue",industry:"Regional retailer",difficulty:6,scenario:"Profit is under pressure. Finance proposes cutting the in-store visual merchandising team, saving $600,000 a year. Stores with a dedicated merchandiser average 11% higher sales per square foot than those without, on otherwise similar traffic.",prompt:"What is the strongest response?",choices:[{id:"a",text:"Approve the cut; $600,000 is certain and the sales link is not"},{id:"b",text:"Reject the cut outright and find savings elsewhere"},{id:"c",text:"Estimate the gross profit inside that 11% before deciding"},{id:"d",text:"Cut half the team to balance both concerns"}],correctChoiceId:"c",work:["The certain benefit is $600,000 of annual payroll savings.","The possible cost is the gross profit generated by an 11% sales-per-square-foot lift.","Multiply the affected stores' sales by 11% and their gross margin; compare that result with $600,000 before cutting."],explanation:"Cost cuts are only wins if the cost was not producing more than it consumed. The 11% gap is the number that decides this, and it is available before you act rather than after."}],a=[{id:"ops-01",mode:"standard",category:"operations",subskill:"rework and root cause",industry:"Cabinet shop",difficulty:1,scenario:"About 30% of finished cabinets come back for rework because measurements were taken wrong at the customer's home.",prompt:"What is the best fix?",choices:[{id:"a",text:"Add a second finishing crew to handle the rework faster"},{id:"b",text:"Fix how measurements are taken and verified"},{id:"c",text:"Build extra time into every schedule for rework"},{id:"d",text:"Offer customers a discount when rework is needed"}],correctChoiceId:"b",explanation:"Rework is pure waste created upstream. Getting the measurement right removes the cost entirely instead of staffing up to absorb it."},{id:"ops-02",mode:"standard",category:"operations",subskill:"non-productive time",industry:"Appliance repair",difficulty:1,scenario:"Your eight technicians each spend about three hours a day driving because jobs are assigned in the order they were booked, not by location.",prompt:"What is the most valuable change?",choices:[{id:"a",text:"Hire two more technicians"},{id:"b",text:"Route each technician's day geographically"},{id:"c",text:"Extend the workday by an hour"},{id:"d",text:"Raise prices to cover the travel time"}],correctChoiceId:"b",explanation:"You are paying for 24 technician-hours a day of driving. Routing recovers billable capacity you already own, at almost no cost."},{id:"ops-03",mode:"standard",category:"operations",subskill:"inventory policy",industry:"Auto repair",difficulty:2,scenario:"Twelve times last month a car sat on a lift for an extra day waiting for a $40 part. Each lift generates about $900 of revenue a day, and you have four lifts.",prompt:"What should you change?",choices:[{id:"a",text:"Stock the common parts even though it ties up cash"},{id:"b",text:"Negotiate faster delivery from your supplier"},{id:"c",text:"Charge customers a fee for parts delays"},{id:"d",text:"Add a fifth lift to absorb the delays"}],correctChoiceId:"a",explanation:"Twelve lost lift-days cost roughly $10,800 in capacity to avoid holding a few hundred dollars of parts. Faster shipping helps, but carrying the cheap high-frequency parts removes the problem outright."},{id:"ops-04",mode:"standard",category:"operations",subskill:"standardization",industry:"Veterinary clinic",difficulty:2,scenario:"Four technicians each run intake their own way. Visit length varies from 20 to 55 minutes for the same appointment type, and chart completeness varies just as much.",prompt:"What is the right first move?",choices:[{id:"a",text:"Set an individual speed target for each technician"},{id:"b",text:"Define one documented intake process and train everyone to it"},{id:"c",text:"Schedule longer appointment slots to absorb the variation"},{id:"d",text:"Replace the slowest technician"}],correctChoiceId:"b",explanation:"With four different processes you cannot tell whether the variation is the person or the method. Standardizing first makes performance comparable and improvement repeatable."},{id:"ops-05",mode:"standard",category:"operations",subskill:"reading process data",industry:"Electronics assembly",difficulty:3,scenario:"Output over four weeks after a new hire started on the test station:",data:{columns:["","Wk 1","Wk 2","Wk 3","Wk 4"],rows:[{label:"Units started",values:["2,000","2,000","2,050","2,100"]},{label:"Units passing test",values:["1,940","1,930","1,780","1,690"]},{label:"Units scrapped",values:["60","70","270","410"]},{label:"Line hours",values:["160","160","162","165"]}]},prompt:"What should you investigate?",choices:[{id:"a",text:"Whether the line is running too fast"},{id:"b",text:"What changed around week 3 to triple the scrap rate"},{id:"c",text:"Whether to add a second test station"},{id:"d",text:"Whether demand justifies the increased starts"}],correctChoiceId:"b",explanation:"Starts barely moved while scrap went from 3% to 20%. A step change like that has a specific cause with a date attached, and finding it is far cheaper than adding capacity to a process producing defects."},{id:"ops-06",mode:"standard",category:"operations",subskill:"work in progress",industry:"Marketing agency",difficulty:3,scenario:"Your team of six has 34 projects open at once. Average delivery time has grown from three weeks to nine. Everyone is busy, nothing ships, and clients are frustrated.",prompt:"What is the most effective change?",choices:[{id:"a",text:"Hire two more people to work through the load"},{id:"b",text:"Limit how many projects are active at once and finish them in sequence"},{id:"c",text:"Ask the team to work longer hours until the backlog clears"},{id:"d",text:"Give each client a longer promised timeline"}],correctChoiceId:"b",explanation:"Thirty-four simultaneous projects means constant context switching and nothing finishing. Capping active work shortens delivery time immediately without adding a single hour of labor."},{id:"ops-07",mode:"standard",category:"operations",subskill:"measuring the wrong thing",industry:"Machine shop",difficulty:4,scenario:"Management bonuses are tied to machine utilization, which is now 94%. Finished-goods inventory has tripled, on-time delivery has fallen from 92% to 71%, and the floor is crowded with partly finished work.",prompt:"What is going wrong?",choices:[{id:"a",text:"The machines are too old to sustain 94% utilization"},{id:"b",text:"The utilization target drives production of things customers have not ordered"},{id:"c",text:"Scheduling software needs to be upgraded"},{id:"d",text:"Delivery is a logistics problem unrelated to the shop floor"}],correctChoiceId:"b",explanation:"Keeping every machine busy is not the same as producing what is due. Rewarding utilization converts cash into inventory and pushes late orders behind work nobody asked for."},{id:"ops-08",mode:"standard",category:"operations",subskill:"automating a broken process",industry:"Property management",difficulty:4,scenario:"Maintenance requests take an average of nine days to close. About 60% of that time is spent going back to tenants for missing details. A vendor is selling a $60,000 workflow system that automates ticket routing and technician dispatch.",prompt:"What should you do?",choices:[{id:"a",text:"Buy the system; automation will compress the nine days"},{id:"b",text:"Fix the intake form so requests arrive complete, then evaluate the system"},{id:"c",text:"Add a coordinator to chase tenants faster"},{id:"d",text:"Set a service-level target and hold technicians to it"}],correctChoiceId:"b",explanation:"Automation speeds up routing, but routing is not where the nine days go. Capturing complete information at intake attacks 60% of the delay and costs almost nothing."},{id:"ops-09",mode:"standard",category:"operations",subskill:"variability versus average",industry:"Hotel housekeeping",difficulty:5,scenario:"Rooms are cleaned in 28 minutes on average, comfortably inside your 35-minute standard. But the spread runs from 18 to 70 minutes, and roughly one in eight guests waits past the 3pm check-in time.",prompt:"What should you work on?",choices:[{id:"a",text:"Lower the average to 25 minutes"},{id:"b",text:"Reduce the variation in cleaning time"},{id:"c",text:"Move check-in to 4pm"},{id:"d",text:"Add housekeeping staff across the board"}],correctChoiceId:"b",explanation:"Guests do not experience your average; they experience the long tail. A healthy mean with a 52-minute spread is what produces late check-ins, so tightening the spread fixes the guest problem."},{id:"ops-10",mode:"standard",category:"operations",subskill:"local optimization",industry:"Food manufacturing",difficulty:5,scenario:"Your mixing department cut its cost per batch 18% by running much larger batches. Since then, changeovers on the packaging line have doubled, finished inventory is up 40%, and two products went out of date last month.",prompt:"How should you read this?",choices:[{id:"a",text:"Mixing improved; packaging needs to catch up"},{id:"b",text:"A local saving created larger costs downstream and overall"},{id:"c",text:"The inventory increase is a normal side effect of efficiency"},{id:"d",text:"Expiry losses are a demand forecasting problem"}],correctChoiceId:"b",explanation:"Departmental savings that push cost onto the next step are not savings. Judge the change on total cost and total throughput, where this one is clearly negative."},{id:"ops-11",mode:"standard",category:"operations",subskill:"adding a step to remove cost",industry:"Custom millwork",difficulty:6,scenario:"A proposed 20-minute pre-production review on every order would add about 55 hours a month of labor. Roughly 15% of orders currently reach the shop with errors, and each one costs an average of nine hours to correct plus a delayed delivery. You run about 220 orders a month.",prompt:"What is the right call?",choices:[{id:"a",text:"Reject it — adding a step slows the process"},{id:"b",text:"Adopt it; the review should cost far less than the errors it prevents"},{id:"c",text:"Apply it only to orders over a certain dollar value"},{id:"d",text:"Adopt it only if it can be done in under 10 minutes"}],correctChoiceId:"b",explanation:"About 33 defective orders a month cost roughly 297 hours to fix, against 55 hours of review. Adding a cheap step upstream to remove an expensive one downstream is usually the highest-return change available."},{id:"ops-12",mode:"standard",category:"operations",subskill:"efficiency versus resilience",industry:"Contract manufacturing",difficulty:6,scenario:"Consolidating to a single supplier would save 7% on materials, worth about $340,000 a year. That supplier is in one region and currently provides 45% of your input. A two-week outage last year, when they were one of three suppliers, cost you roughly $200,000.",prompt:"What is the strongest way to think about this?",choices:[{id:"a",text:"Take the savings; $340,000 a year outweighs a one-off $200,000 event"},{id:"b",text:"Weigh the savings against the larger loss an outage would now cause with no alternative"},{id:"c",text:"Reject consolidation on principle; never single-source"},{id:"d",text:"Consolidate and negotiate penalty clauses to cover outages"}],correctChoiceId:"b",explanation:"The $200,000 figure came from a world where two other suppliers absorbed the shock. Removing them changes the size of the downside, so the savings must be compared against the new exposure, not the old one."}],r=[{id:"peo-01",mode:"standard",category:"people",subskill:"owner time value",industry:"Law practice",difficulty:1,scenario:"You bill $250 an hour and have a waiting list of clients. You currently spend six hours a week scanning and filing documents. An assistant would do it for $22 an hour.",prompt:"What should you do?",choices:[{id:"a",text:"Keep doing it yourself to control costs"},{id:"b",text:"Hire the assistant and use the freed hours on client work"},{id:"c",text:"Do the filing after hours instead"},{id:"d",text:"Stop filing documents altogether"}],correctChoiceId:"b",explanation:"Six hours of your time is worth $1,500 against roughly $132 of assistant cost, and you have clients waiting to absorb those hours."},{id:"peo-02",mode:"standard",category:"people",subskill:"onboarding ownership",industry:"Retail chain",difficulty:1,scenario:"A new store associate started Monday. Nobody was assigned to train them, so they have spent three days shadowing whoever happens to be free.",prompt:"What should you do?",choices:[{id:"a",text:"Give it more time; people learn by observing"},{id:"b",text:"Assign a specific person and a defined first-week plan"},{id:"c",text:"Move them to a quieter store"},{id:"d",text:"Send them home until a manager is available"}],correctChoiceId:"b",explanation:"Training that belongs to everyone belongs to no one. Naming an owner and a plan is the difference between a productive hire in two weeks and a resignation in two months."},{id:"peo-03",mode:"standard",category:"people",subskill:"promotion misfit",industry:"Software company",difficulty:2,scenario:"You promoted your best engineer to engineering manager six months ago. Her team's output has dropped, she works nights to keep coding, and she has said she misses building.",prompt:"What is the best response?",choices:[{id:"a",text:"Give her management training and more time to adjust"},{id:"b",text:"Create a senior technical track and move her back to building"},{id:"c",text:"Reduce her team size so management is easier"},{id:"d",text:"Replace her with an external manager and let her leave if she wants"}],correctChoiceId:"b",explanation:"You converted an excellent individual contributor into a struggling manager and lost both. A senior technical path keeps the talent and lets you hire someone who actually wants to manage."},{id:"peo-04",mode:"standard",category:"people",subskill:"single point of failure",industry:"Specialty bakery",difficulty:2,scenario:"One baker knows every recipe and holds them in his head. He has not taken a vacation in two years, and production stops entirely on the rare days he is out.",prompt:"What should you do?",choices:[{id:"a",text:"Give him a raise to reduce the risk of losing him"},{id:"b",text:"Document the recipes and cross-train a second baker"},{id:"c",text:"Require him to give more notice before taking days off"},{id:"d",text:"Hire an assistant to help him work faster"}],correctChoiceId:"b",explanation:"A raise makes him more likely to stay but does nothing about illness, burnout or a better offer. Documentation and a trained backup convert a single point of failure into a normal role."},{id:"peo-05",mode:"standard",category:"people",subskill:"skill, will, or system",industry:"Call center",difficulty:3,scenario:"Four agents on the same team, same shift, same script:",data:{columns:["Agent","Calls/day","Conversion"],rows:[{label:"Agent A",values:["48","9%"]},{label:"Agent B",values:["51","10%"]},{label:"Agent C",values:["47","8%"]},{label:"Agent D",values:["49","26%"]}],note:"All four were hired within the same two months and trained together."},prompt:"What is the most valuable next step?",choices:[{id:"a",text:"Put A, B and C on performance improvement plans"},{id:"b",text:"Find out what Agent D does differently and teach it"},{id:"c",text:"Replace the script, since three of four underperform"},{id:"d",text:"Increase the commission rate to motivate the team"}],correctChoiceId:"b",explanation:"One person hitting 26% on the same inputs proves the result is achievable. The cheapest source of improvement is already inside the building; copy it before you replace anything."},{id:"peo-06",mode:"standard",category:"people",subskill:"delegating outcomes",industry:"Logistics",difficulty:3,scenario:"You handed your dispatch supervisor a 14-step checklist for building the daily route plan. He follows it exactly, and every exception still comes back to you, which is about a dozen times a day.",prompt:"What should change?",choices:[{id:"a",text:"Expand the checklist to cover more exception cases"},{id:"b",text:"Give him the objective, the constraints, and authority to decide"},{id:"c",text:"Move exception handling to a different person"},{id:"d",text:"Hold a daily meeting to clear exceptions in one batch"}],correctChoiceId:"b",explanation:"You delegated the steps but kept the judgment, so every case the checklist did not anticipate returns to you. Delegating the outcome and the boundaries is what actually removes you from the loop."},{id:"peo-07",mode:"standard",category:"people",subskill:"hiring timing",industry:"Growing agency",difficulty:4,scenario:"Your team is at 100% utilization and turning away work. A strong candidate takes about eight weeks to hire and three months to become fully productive. Your pipeline for the next two quarters is strong and contracted.",prompt:"When should you hire?",choices:[{id:"a",text:"Now, because productive capacity arrives about five months out"},{id:"b",text:"Once the team is visibly overloaded and quality slips"},{id:"c",text:"After the contracted work is delivered, to be safe"},{id:"d",text:"Never — use contractors so the cost stays variable"}],correctChoiceId:"a",explanation:"The lag between deciding to hire and getting useful capacity is about five months. Waiting for visible pain means the relief arrives long after the damage, and here the demand is already contracted."},{id:"peo-08",mode:"standard",category:"people",subskill:"high performer, negative externality",industry:"Sales organization",difficulty:4,scenario:"Your top rep produces 30% of revenue. He also refuses to use the CRM, publicly dismisses the sales process, and two of your four other reps have privately said they are considering leaving because of him.",prompt:"What is the right action?",choices:[{id:"a",text:"Protect the revenue and tolerate the behavior"},{id:"b",text:"Set explicit behavioral expectations with real consequences, and prepare for either outcome"},{id:"c",text:"Terminate him immediately to protect the team"},{id:"d",text:"Move him to a solo territory so he affects no one"}],correctChoiceId:"b",explanation:"Tolerating it tells the other 70% that the rules are optional, and losing two reps costs more than the one you kept. Naming the standard with consequences is the only path that can both keep him and keep the team."},{id:"peo-09",mode:"standard",category:"people",subskill:"coach or replace",industry:"Manufacturing",difficulty:5,scenario:"A supervisor hired 14 months ago runs the lowest-performing shift on every metric. He has never been given targets, has had no one-on-one in a year, and his two peers both received formal training he did not.",prompt:"What should you do?",choices:[{id:"a",text:"Replace him; 14 months is enough time to prove himself"},{id:"b",text:"Give him the targets, training and feedback his peers received, then judge"},{id:"c",text:"Move him to a non-supervisory role"},{id:"d",text:"Reassign his shift to a stronger supervisor"}],correctChoiceId:"b",explanation:"You cannot conclude someone failed at a job they were never actually given the conditions to do. Supplying the missing inputs is fast, cheap, and makes the eventual decision defensible either way."},{id:"peo-10",mode:"standard",category:"people",subskill:"span of control",industry:"Home care agency",difficulty:5,scenario:"You have grown from 20 to 95 caregivers in 18 months. One scheduler still handles every assignment, callout and complaint. Missed shifts have tripled and client complaints are up sharply.",prompt:"What is the core problem?",choices:[{id:"a",text:"The scheduler is underperforming and needs replacing"},{id:"b",text:"The structure never changed as the organization grew nearly fivefold"},{id:"c",text:"Caregivers are less reliable than they used to be"},{id:"d",text:"Clients have become more demanding"}],correctChoiceId:"b",explanation:"A structure that worked for 20 people rarely survives 95. This is an organizational design problem, and replacing the person just puts someone new into the same impossible job."},{id:"peo-11",mode:"standard",category:"people",subskill:"incentive design",industry:"Auto dealership",difficulty:6,scenario:"You paid service advisors a commission on parts and labor revenue. Revenue per repair order rose 22%. Repeat service visits fell 15%, the online rating dropped from 4.5 to 3.8, and warranty complaints about unnecessary work doubled.",prompt:"What is the right conclusion?",choices:[{id:"a",text:"The incentive works; the ratings issue is a separate service problem"},{id:"b",text:"The incentive is buying short-term revenue by spending customer trust"},{id:"c",text:"Advisors need training on how to explain recommended work"},{id:"d",text:"Ratings and repeat visits are seasonal and should be ignored"}],correctChoiceId:"b",explanation:"People optimize what you pay them for, including in ways you did not intend. Three independent measures moved against you at once, which is the signature of an incentive borrowing from future revenue."},{id:"peo-12",mode:"standard",category:"people",subskill:"owner as constraint",industry:"Multi-location services",difficulty:6,scenario:"You own four locations. You personally approve every quote over $5,000, interview every hire, and resolve every escalation. Growth has flattened for three quarters, your managers routinely wait on you, and you are working 70 hours a week.",prompt:"What is the highest-leverage change?",choices:[{id:"a",text:"Work more efficiently so decisions clear faster"},{id:"b",text:"Hire an executive assistant to manage your queue"},{id:"c",text:"Move decision rights to managers with clear limits and a review cadence"},{id:"d",text:"Pause expansion until you can personally keep up"}],correctChoiceId:"c",explanation:"Every decision routes through one person, so the company can only grow as fast as that person's calendar. Speeding yourself up raises the ceiling slightly; moving the decisions removes the ceiling."}],s=[{id:"pri-01",mode:"standard",category:"prioritization",subskill:"blocking vs non-blocking",industry:"Coffee shop",difficulty:1,scenario:"It is 7:15am, your busiest hour. The espresso machine just stopped working, you are low on napkins, and this week's Instagram post is not written.",prompt:"What do you handle first?",choices:[{id:"a",text:"Write the Instagram post"},{id:"b",text:"Get the espresso machine working"},{id:"c",text:"Order more napkins"},{id:"d",text:"Update the menu board pricing"}],correctChoiceId:"b",explanation:"The machine blocks nearly all revenue during your highest-volume hour. Everything else can wait a few hours at almost no cost."},{id:"pri-02",mode:"standard",category:"prioritization",subskill:"idle resources first",industry:"Landscaping",difficulty:1,scenario:"A four-person crew is parked in the yard waiting for you to tell them which site to go to. You are in the middle of reviewing logo concepts for a rebrand.",prompt:"What should you do?",choices:[{id:"a",text:"Finish the logo review, then dispatch the crew"},{id:"b",text:"Dispatch the crew immediately, then return to the logo"},{id:"c",text:"Ask the crew to pick a site themselves and keep reviewing"},{id:"d",text:"Send the crew home and restart tomorrow"}],correctChoiceId:"b",explanation:"Four idle people cost real money every minute. The rebrand has no deadline attached to it today."},{id:"pri-03",mode:"standard",category:"prioritization",subskill:"blast radius",industry:"B2B SaaS",difficulty:2,scenario:"Three items landed this morning. A visual glitch affects about 3% of users. A checkout bug stops 100% of new signups from paying. Your largest customer asked for a reporting feature.",prompt:"What gets worked on first?",choices:[{id:"a",text:"The reporting feature, to protect the largest account"},{id:"b",text:"The visual glitch, since it is quick"},{id:"c",text:"The checkout bug"},{id:"d",text:"Split the team across all three"}],correctChoiceId:"c",explanation:"The checkout bug stops every new dollar from entering the business. It is both the widest blast radius and the only one actively compounding."},{id:"pri-04",mode:"standard",category:"prioritization",subskill:"time-boxed windows",industry:"Garden center",difficulty:2,scenario:"You are three weeks from the spring rush, which produces 60% of your annual revenue. Your options are to hire and train seasonal staff, remodel the checkout counter, renegotiate a supplier contract that renews in November, or rebuild the website.",prompt:"What should you do now?",choices:[{id:"a",text:"Hire and train seasonal staff"},{id:"b",text:"Remodel the checkout counter"},{id:"c",text:"Renegotiate the November supplier contract"},{id:"d",text:"Rebuild the website"}],correctChoiceId:"a",explanation:"Only one of these has a window that closes. Staffing must be done before the rush; the other three are equally available in June."},{id:"pri-05",mode:"standard",category:"prioritization",subskill:"effort vs impact",industry:"Online retailer",difficulty:3,scenario:"Four proposals are on the table, each estimated by the same team:",data:{columns:["Initiative","Effort","Annual impact"],rows:[{label:"Rebuild the mobile checkout",values:["3 weeks","+$420,000"]},{label:"New loyalty program",values:["10 weeks","+$500,000"]},{label:"Warehouse layout redesign",values:["6 weeks","+$180,000"]},{label:"Brand refresh",values:["8 weeks","Not estimated"]}]},prompt:"What should the team do first?",choices:[{id:"a",text:"The loyalty program, because it has the largest impact"},{id:"b",text:"The mobile checkout rebuild"},{id:"c",text:"The warehouse redesign, because operations underpins everything"},{id:"d",text:"The brand refresh, because it improves all other efforts"}],correctChoiceId:"b",explanation:"Checkout returns about $140,000 per week of effort versus $50,000 for the loyalty program. Doing it first also frees the team sooner to attempt the second item."},{id:"pri-06",mode:"standard",category:"prioritization",subskill:"compounding problems",industry:"Boutique hotel",difficulty:3,scenario:"Four issues are open: the lobby carpet is dated, online reviews have slipped from 4.6 to 4.1 over two months, the breakfast vendor raised prices 8%, and your booking engine takes six clicks to reserve a room.",prompt:"Which deserves attention first?",choices:[{id:"a",text:"The dated lobby carpet"},{id:"b",text:"The 8% breakfast cost increase"},{id:"c",text:"The slide in review scores"},{id:"d",text:"The six-click booking flow"}],correctChoiceId:"c",explanation:"Review scores drive future bookings, so the damage compounds every week it continues. The other three are real but static costs."},{id:"pri-07",mode:"standard",category:"prioritization",subskill:"deciding what not to do",industry:"Consumer products",difficulty:4,scenario:"You sell three product lines. Line A is 70% of revenue and growing. Line B is 25% and flat. Line C is 5%, shrinking, and consumes roughly 40% of your operations team's time because of its custom packaging.",prompt:"What is the strongest move?",choices:[{id:"a",text:"Increase marketing on Line C to revive it"},{id:"b",text:"Discontinue or spin off Line C and redeploy the freed time"},{id:"c",text:"Hire an operations person dedicated to Line C"},{id:"d",text:"Raise Line C prices to cover the extra effort"}],correctChoiceId:"b",explanation:"Line C consumes 40% of your operating capacity to produce 5% of revenue, and it is declining. Killing it is the cheapest way to buy capacity for the line that is actually growing."},{id:"pri-08",mode:"standard",category:"prioritization",subskill:"urgent vs important",industry:"Accounting firm",difficulty:4,scenario:"Your team spends about 12 hours a week chasing clients for missing documents. There is also a backlog of 30 returns due in two weeks. You have one week of your own time to invest.",prompt:"What is the best use of that week?",choices:[{id:"a",text:"Personally prepare returns to clear the backlog"},{id:"b",text:"Build an intake checklist and automated document reminders"},{id:"c",text:"Hire a temporary preparer for the season"},{id:"d",text:"Extend office hours through the deadline"}],correctChoiceId:"b",explanation:"The 12 hours a week lost to chasing documents is the recurring cause of the backlog. Fixing intake pays back within the same season and every season after; preparing returns yourself buys one week only."},{id:"pri-09",mode:"standard",category:"prioritization",subskill:"sequencing dependencies",industry:"Franchise restaurant",difficulty:5,scenario:"You plan to open four new locations this year. Your existing three locations run on undocumented processes that vary store to store, and your best general manager is the only person who can train new staff.",prompt:"What should happen first?",choices:[{id:"a",text:"Sign the four leases while good sites are available"},{id:"b",text:"Document and standardize operations, and build a second trainer"},{id:"c",text:"Open one location and learn from it before the other three"},{id:"d",text:"Raise capital so all four can open simultaneously"}],correctChoiceId:"b",explanation:"Expansion copies whatever system you have. With undocumented processes and a single trainer, opening first guarantees four inconsistent stores and one exhausted manager."},{id:"pri-10",mode:"standard",category:"prioritization",subskill:"owner opportunity cost",industry:"Professional services",difficulty:5,scenario:"You bill at $300 an hour and the firm is at capacity. You currently spend eight hours a week on bookkeeping. A bookkeeper costs $45 an hour and would need about ten hours a week. You are also the only person who can close new engagements, and demand exceeds what you can close.",prompt:"What should you do?",choices:[{id:"a",text:"Keep bookkeeping in-house to protect margin"},{id:"b",text:"Hire the bookkeeper and move that time to closing engagements"},{id:"c",text:"Hire the bookkeeper and use the time to reduce your hours"},{id:"d",text:"Buy accounting software and keep doing it yourself faster"}],correctChoiceId:"b",explanation:"Eight hours of your time is worth $2,400 against $450 of bookkeeper cost. The reason it is clearly correct here is that demand exceeds your closing capacity, so the freed hours convert directly into revenue."},{id:"pri-11",mode:"standard",category:"prioritization",subskill:"reversible vs irreversible",industry:"Software startup",difficulty:6,scenario:"Your team must decide four things this quarter: which analytics vendor to use, whether to sign a five-year office lease, what to name the second product, and which pricing page layout to ship.",prompt:"Which decision deserves the most deliberation time?",choices:[{id:"a",text:"The analytics vendor"},{id:"b",text:"The five-year office lease"},{id:"c",text:"The second product's name"},{id:"d",text:"The pricing page layout"}],correctChoiceId:"b",explanation:"Deliberation should scale with how hard a decision is to undo. Vendors can be switched, names changed, and layouts tested cheaply; a five-year lease locks in cost and location through several plausible futures."},{id:"pri-12",mode:"standard",category:"prioritization",subskill:"signal vs noise",industry:"Subscription box",difficulty:6,scenario:"One prominent customer posted a detailed public complaint about your packaging and it is getting attention internally. Separately, your month-two retention has drifted from 71% to 64% over five months without anyone raising it.",prompt:"Where should leadership put its attention?",choices:[{id:"a",text:"The public complaint, since visible reputation issues spread fastest"},{id:"b",text:"The retention decline"},{id:"c",text:"Neither — both are within normal variation"},{id:"d",text:"Redesign packaging, which addresses both at once"}],correctChoiceId:"b",explanation:"One loud data point is an anecdote; a seven-point retention slide across five months is a trend that silently resets the value of every customer you acquire. Answer the complaint, but do not let it set the agenda."}],n=[{id:"res-01",mode:"standard",category:"resource",subskill:"highest-value use of a scarce asset",industry:"Mobile detailing",difficulty:1,scenario:"You have one van available today and two jobs booked. Job A is $900 and the customer needs it today. Job B is $200 and the customer is flexible about the date.",prompt:"What should you do?",choices:[{id:"a",text:"Run Job B first because it is quicker"},{id:"b",text:"Run Job A today and reschedule Job B"},{id:"c",text:"Split the van's day and do half of each"},{id:"d",text:"Cancel both and rebook a fuller day"}],correctChoiceId:"b",work:["Value per use of the scarce van: Job A = $900; Job B = $200.","$900 ÷ $200 = 4.5, so Job A is worth 4.5 times as much.","Job B is flexible and can be moved; Job A's deadline cannot."],explanation:"One scarce asset should go to the highest-value use. Job A is worth 4.5 times as much and is the only one with a real deadline."},{id:"res-02",mode:"standard",category:"resource",subskill:"spend where the loss is",industry:"Independent pharmacy",difficulty:1,scenario:"You have $10,000 to spend. Your refrigeration unit fails about twice a month, and each failure spoils roughly $3,000 of inventory. You have also been considering new exterior signage.",prompt:"Where should the money go?",choices:[{id:"a",text:"New exterior signage"},{id:"b",text:"Replacing the refrigeration unit"},{id:"c",text:"Split it evenly between the two"},{id:"d",text:"Hold the cash until the next quarter"}],correctChoiceId:"b",work:["Expected monthly spoilage = 2 failures × $3,000 = about $6,000.","A $10,000 replacement pays back in roughly $10,000 ÷ $6,000 = 1.7 months.","Signage has an uncertain return; refrigeration stops a measured recurring loss."],explanation:"The refrigeration failures destroy about $6,000 a month. That is a certain, recurring loss you can stop, which beats a speculative gain from signage."},{id:"res-03",mode:"standard",category:"resource",subskill:"cost per acquisition",industry:"Online education",difficulty:2,scenario:"Two channels ran last month at the same spend. Channel A brought 400 signups at $25 each. Channel B brought 120 signups at $83 each. Both channels convert to paid at the same rate and neither is near saturation.",prompt:"How should you allocate next month's budget?",choices:[{id:"a",text:"Shift budget toward Channel A"},{id:"b",text:"Shift budget toward Channel B for the higher-intent audience"},{id:"c",text:"Keep the split even to stay diversified"},{id:"d",text:"Pause both and rebuild the landing page"}],correctChoiceId:"a",work:["Channel A costs $25 per signup; Channel B costs $83.","$83 ÷ $25 = 3.32, so B costs more than three times as much for the same outcome.","Because conversion and remaining capacity are equal, shift the next dollar toward A."],explanation:"Same conversion rate, same headroom, and a third of the cost per signup. With those facts stated, Channel A is simply better use of the same dollar."},{id:"res-04",mode:"standard",category:"resource",subskill:"hire against the gap",industry:"Commercial cleaning",difficulty:2,scenario:"You can afford one hire. Your two sales reps are closing 40% of a full pipeline and are turning away walkthrough requests. Your crews finish their routes with about two hours of slack per day.",prompt:"Who should you hire?",choices:[{id:"a",text:"Another cleaning crew"},{id:"b",text:"Another salesperson"},{id:"c",text:"An office administrator"},{id:"d",text:"A marketing coordinator"}],correctChoiceId:"b",explanation:"Crews have slack, so delivery is not the limit. Sales is turning away qualified walkthroughs, which is demand you have already paid to create and are throwing away."},{id:"res-05",mode:"standard",category:"resource",subskill:"capital against the constraint",industry:"HVAC services",difficulty:3,scenario:"You have $50,000 to deploy. Current state of the business:",data:{rows:[{label:"Signed work not yet installed",values:["$600,000"]},{label:"Install schedule",values:["5 weeks behind"]},{label:"Crew utilization",values:["100%"]},{label:"Leads",values:["Up 18% month over month"]},{label:"Close rate",values:["Healthy and stable"]}]},prompt:"What is the best use of the capital?",choices:[{id:"a",text:"Increase advertising"},{id:"b",text:"Hire another salesperson"},{id:"c",text:"Expand install capacity"},{id:"d",text:"Redesign the website"}],correctChoiceId:"c",explanation:"You are already sitting on $600,000 of sold work you cannot install. Capital spent on more demand lengthens the backlog; capital spent on install capacity converts backlog into cash."},{id:"res-06",mode:"standard",category:"resource",subskill:"diminishing returns",industry:"Direct-to-consumer brand",difficulty:3,scenario:"Results as you scaled one channel over three months:",data:{columns:["","Month 1","Month 2","Month 3"],rows:[{label:"Spend",values:["$20,000","$40,000","$80,000"]},{label:"Customers acquired",values:["500","870","1,020"]},{label:"Cost per customer",values:["$40","$46","$78"]}],note:"Average gross profit per customer is $60."},prompt:"What should you do with next month's budget?",choices:[{id:"a",text:"Double spend again to keep growth compounding"},{id:"b",text:"Pull spend back toward the range that stayed under $60 per customer"},{id:"c",text:"Hold spend at $80,000 and wait for the channel to recover"},{id:"d",text:"Cut the channel entirely"}],correctChoiceId:"b",work:["At $80,000 spend, average acquisition cost is $78 against only $60 of gross profit.","The incremental 150 customers from $40,000 to $80,000 cost $40,000 ÷ 150 ≈ $267 each.","The channel still works at lower spend, so pull back below the point of negative marginal return."],explanation:"The last doubling bought customers above their $60 gross profit, so those dollars lose money. The channel is still profitable at lower volume, so pull back rather than abandon it."},{id:"res-07",mode:"standard",category:"resource",subskill:"margin per constrained hour",industry:"Print shop",difficulty:4,scenario:"Your large-format printer is booked solid and is the limit on output. Banner jobs earn $180 of margin and occupy the printer for 3 hours. Decal jobs earn $90 of margin and occupy it for 45 minutes. Both have unlimited demand.",prompt:"How should you fill the printer's schedule?",choices:[{id:"a",text:"Prioritize banners, which earn twice the margin per job"},{id:"b",text:"Prioritize decals"},{id:"c",text:"Alternate evenly to keep both customer types"},{id:"d",text:"Raise decal prices and keep the current mix"}],correctChoiceId:"b",work:["Banner margin per constrained hour = $180 ÷ 3 = $60.","Decal margin per constrained hour = $90 ÷ 0.75 = $120.","Decals generate twice the margin from the resource that is actually scarce."],explanation:"On a constrained machine the right unit is margin per machine hour: banners earn $60 an hour, decals earn $120. Total margin per job is the wrong comparison when time is what is scarce."},{id:"res-08",mode:"standard",category:"resource",subskill:"scarce specialist time",industry:"Enterprise software",difficulty:4,scenario:"Your one senior engineer has four weeks of capacity. Customer X ($40,000/year, renews in two months) wants a custom integration that will take all four weeks and help only them. A platform fix would take three weeks and remove a recurring problem hitting 30% of your 200 customers.",prompt:"How should you allocate the four weeks?",choices:[{id:"a",text:"Build the custom integration to secure the renewal"},{id:"b",text:"Do the platform fix, then use the spare week on Customer X's renewal risk"},{id:"c",text:"Attempt both at half speed"},{id:"d",text:"Do neither until you hire a second engineer"}],correctChoiceId:"b",work:["The platform issue reaches 30% × 200 = about 60 customers.","It consumes three weeks versus four weeks for a one-customer integration.","Fix the shared problem, then spend the remaining week addressing Customer X's renewal risk directly."],explanation:"The platform fix helps roughly 60 customers instead of one and costs less time. The remaining week is enough to address the renewal directly rather than by building bespoke software."},{id:"res-09",mode:"standard",category:"resource",subskill:"fixed vs variable commitment",industry:"Logistics",difficulty:5,scenario:"Volume has grown 30% and your own trucks are full. Buying two trucks costs $260,000 and lowers cost per load by 20% versus using outside carriers. About 60% of your growth came from one retail client whose contract is up for rebid in seven months.",prompt:"What is the most defensible move?",choices:[{id:"a",text:"Buy the two trucks to capture the lower cost per load"},{id:"b",text:"Cover the growth with outside carriers until the rebid is settled"},{id:"c",text:"Buy one truck and use carriers for the rest"},{id:"d",text:"Decline the extra volume to protect service levels"}],correctChoiceId:"b",explanation:"The savings are real but the volume is not yet durable — most of it rides on a contract that could disappear in seven months. Paying more per load to keep the cost variable is what you are buying, and it is worth it here."},{id:"res-10",mode:"standard",category:"resource",subskill:"starving the funding engine",industry:"Media company",difficulty:5,scenario:"Your events business produces $4M of revenue at 35% margin and funds everything. A new subscription product has 900 subscribers, grows 15% a month, and loses money today. Leadership proposes moving the events team onto subscriptions for two quarters to accelerate it.",prompt:"What is the main risk to weigh?",choices:[{id:"a",text:"Subscriptions may never reach the margin events produces"},{id:"b",text:"Redirecting the events team could damage the cash flow paying for the bet"},{id:"c",text:"Subscribers may resent being sold events"},{id:"d",text:"The events brand could be diluted by the new product"}],correctChoiceId:"b",explanation:"Growth bets are funded by something. Consuming the operating engine to feed the new product can end the runway before the product matures, which is how promising bets die."},{id:"res-11",mode:"standard",category:"resource",subskill:"allocating under uncertainty",industry:"Consumer app",difficulty:6,scenario:"You have $200,000 and three proposals, each championed confidently: a brand campaign, a referral program, and a retention overhaul. Nobody can say where users are actually dropping off, and the analytics have never been instrumented.",prompt:"What is the best use of the first dollars?",choices:[{id:"a",text:"Split the budget evenly across all three"},{id:"b",text:"Fund the retention overhaul, since retention usually matters most"},{id:"c",text:"Instrument the funnel first, then allocate the remainder"},{id:"d",text:"Fund the referral program, which is cheapest to reverse"}],correctChoiceId:"c",explanation:"Allocating $200,000 across three guesses buys three underfunded experiments and no knowledge. Measurement is cheap relative to the budget and turns the next decision from a guess into a choice."},{id:"res-12",mode:"standard",category:"resource",subskill:"opportunity cost across horizons",industry:"Manufacturing",difficulty:6,scenario:"You can fund exactly one project. Project A returns $300,000 within 12 months and requires your plant manager full-time for six months. Project B returns $250,000 a year starting in year two and requires the same person for the same six months. Your plant is currently running at 97% on-time delivery and has no slack.",prompt:"What matters most in choosing?",choices:[{id:"a",text:"The larger first-year return of Project A"},{id:"b",text:"The recurring nature of Project B's return"},{id:"c",text:"What happens to plant performance while the manager is unavailable"},{id:"d",text:"Which project the team is more excited about"}],correctChoiceId:"c",explanation:"Both projects consume the identical scarce resource, so their real cost is whatever a 97%-utilized plant does without its manager for six months. That cost is common to both and is likely larger than the gap between them."}],d=[{id:"sal-01",mode:"standard",category:"sales",subskill:"leak before spend",industry:"Home services",difficulty:1,scenario:"Your ads generate about 900 phone calls a month. Roughly 40% of those calls go unanswered because nobody is at the desk.",prompt:"What should you fix first?",choices:[{id:"a",text:"Increase the ad budget to generate more calls"},{id:"b",text:"Make sure incoming calls get answered"},{id:"c",text:"Change the ad creative"},{id:"d",text:"Add a chat widget to the website"}],correctChoiceId:"b",explanation:"You are already paying for 360 calls a month that nobody picks up. Answering them costs far less than buying the same volume again."},{id:"sal-02",mode:"standard",category:"sales",subskill:"measurement",industry:"Local retail",difficulty:1,scenario:"You spend $10,000 a month across radio, social ads, direct mail and sponsorships. You have never asked or recorded where customers heard about you.",prompt:"What is the highest-value next step?",choices:[{id:"a",text:"Cut the budget in half to reduce risk"},{id:"b",text:"Move the whole budget to social, which is easiest to measure"},{id:"c",text:"Start capturing lead source before changing the mix"},{id:"d",text:"Double the budget to see if revenue moves"}],correctChoiceId:"c",explanation:"Any change you make now is unmeasurable, so you will learn nothing from it. Attribution is cheap and turns the next $10,000 into an informed decision."},{id:"sal-03",mode:"standard",category:"sales",subskill:"sales capacity vs demand",industry:"Insurance agency",difficulty:2,scenario:"Each of your salespeople can comfortably handle 20 appointments a week. They are currently averaging 7 appointments a week and closing 35% of them.",prompt:"What is the best next move?",choices:[{id:"a",text:"Hire another salesperson"},{id:"b",text:"Generate more qualified appointments"},{id:"c",text:"Lower prices to raise the close rate"},{id:"d",text:"Increase commission to motivate the team"}],correctChoiceId:"b",explanation:"Your team is using about a third of its capacity and closing at a healthy rate. Adding people or incentives does nothing when the shortage is appointments."},{id:"sal-04",mode:"standard",category:"sales",subskill:"conversion vs traffic",industry:"E-commerce",difficulty:2,scenario:"Your store gets 60,000 visitors a month and converts 0.4% of them. Comparable stores in your category convert 2%. Traffic costs $0.90 per visitor.",prompt:"Where is the leverage?",choices:[{id:"a",text:"Buying more traffic"},{id:"b",text:"Improving conversion on the traffic you already pay for"},{id:"c",text:"Expanding into a new sales channel"},{id:"d",text:"Reducing product prices"}],correctChoiceId:"b",explanation:"You already pay $54,000 a month for visitors and convert a fifth as well as your category. Moving conversion from 0.4% to 0.8% doubles revenue without spending another dollar on traffic."},{id:"sal-05",mode:"standard",category:"sales",subskill:"funnel diagnosis",industry:"Solar installer",difficulty:3,scenario:"Two months of funnel data:",data:{columns:["","Last month","This month"],rows:[{label:"Leads",values:["500","700"]},{label:"Appointments set",values:["180","240"]},{label:"Appointments held",values:["150","196"]},{label:"Sales",values:["72","94"]},{label:"Jobs completed",values:["70","61"]}],note:"Customer wait times are increasing."},prompt:"Where should management focus?",choices:[{id:"a",text:"Marketing"},{id:"b",text:"Sales"},{id:"c",text:"Production"},{id:"d",text:"Pricing"}],correctChoiceId:"c",explanation:"Every stage improved except completions, which fell from 70 to 61 while sales rose to 94. The business is selling faster than it can deliver, and the wait times confirm it."},{id:"sal-06",mode:"standard",category:"sales",subskill:"lead quality",industry:"B2B services",difficulty:3,scenario:"You switched lead sources at the start of this month:",data:{columns:["","Old source","New source"],rows:[{label:"Leads per month",values:["220","640"]},{label:"Cost per lead",values:["$95","$28"]},{label:"Reached by phone",values:["61%","22%"]},{label:"Closed deals",values:["31","26"]}]},prompt:"What should you conclude?",choices:[{id:"a",text:"The new source is better — three times the leads at a third of the cost"},{id:"b",text:"The new source costs more per deal and consumes far more rep time"},{id:"c",text:"The sales team needs better phone scripts"},{id:"d",text:"Nothing yet; one month is never enough to judge"}],correctChoiceId:"b",explanation:"Old source: $20,900 for 31 deals, about $674 each. New source: $17,920 for 26 deals, about $689 each, while burning reps through three times the volume. Cost per lead flattered a worse outcome."},{id:"sal-07",mode:"standard",category:"sales",subskill:"correlation and attribution",industry:"Restaurant group",difficulty:4,scenario:"You launched a billboard campaign in June. June sales rose 22%. June is also the first month of your peak season, and last June sales rose 19% with no billboards.",prompt:"What can you conclude about the billboards?",choices:[{id:"a",text:"They produced a 22% lift and should be expanded"},{id:"b",text:"They produced roughly a 3-point lift at most, which may not cover their cost"},{id:"c",text:"They had no effect at all"},{id:"d",text:"Billboards cannot be evaluated, so judge them on brand value"}],correctChoiceId:"b",explanation:"Seasonality already explains 19 of the 22 points. The honest estimate of the campaign's contribution is the difference, and that is what has to justify the spend."},{id:"sal-08",mode:"standard",category:"sales",subskill:"price objection diagnosis",industry:"Commercial equipment",difficulty:4,scenario:"Your reps say you lose deals on price. Your win rate is 22%. When you reviewed 40 lost deals, 31 of the buyers chose a competitor priced within 5% of your quote, and most cited slower response and unclear scope.",prompt:"What should you act on?",choices:[{id:"a",text:"Cut prices by 10% to become competitive"},{id:"b",text:"Improve quote turnaround and scope clarity"},{id:"c",text:"Add a discount approval process for reps"},{id:"d",text:"Retrain reps on objection handling scripts"}],correctChoiceId:"b",explanation:"Buyers paid essentially the same price elsewhere, so price was the story rather than the reason. Cutting price would give away margin to fix a problem that is actually about responsiveness and clarity."},{id:"sal-09",mode:"standard",category:"sales",subskill:"growth masking churn",industry:"Subscription service",difficulty:5,scenario:"You added 1,200 customers this quarter, a record. Total customers grew by 150. Acquisition cost per customer rose 12%, and your team wants to raise the acquisition budget to hit the annual growth target.",prompt:"What should you do?",choices:[{id:"a",text:"Approve the budget increase; acquisition is clearly working"},{id:"b",text:"Find out why roughly 1,050 customers left before spending more"},{id:"c",text:"Cut acquisition spend and focus purely on profitability"},{id:"d",text:"Raise prices to offset the higher acquisition cost"}],correctChoiceId:"b",explanation:"You are buying customers who leave almost as fast as they arrive, at rising cost. More budget scales the leak; every point of retention recovered makes all future acquisition cheaper."},{id:"sal-10",mode:"standard",category:"sales",subskill:"diagnosis before prescription",industry:"Industrial distribution",difficulty:5,scenario:"Sales declined 20% this month with no obvious cause.",prompt:"What should you do first?",choices:[{id:"a",text:"Replace the sales manager"},{id:"b",text:"Increase advertising to rebuild volume"},{id:"c",text:"Lower prices to win back share"},{id:"d",text:"Determine where in the funnel the decline occurred"}],correctChoiceId:"d",explanation:"A 20% drop could come from traffic, lead quality, appointments, close rate, or a lost account, and each has a different fix. Every other option is an expensive guess made before the diagnosis."},{id:"sal-11",mode:"standard",category:"sales",subskill:"second-order effects of promotion",industry:"Consumer electronics retail",difficulty:6,scenario:"You have run a deep sitewide discount at the end of each of the last five months. Discount-month revenue is strong. Revenue in the first three weeks of each month has fallen steadily, and full-price sell-through is down 30% year over year.",prompt:"What is happening?",choices:[{id:"a",text:"Demand is genuinely growing and promotions are capturing it"},{id:"b",text:"Customers have learned to wait, shifting sales from full price to discount"},{id:"c",text:"Competitors are undercutting you in the first three weeks"},{id:"d",text:"The discount is too shallow to drive enough volume"}],correctChoiceId:"b",explanation:"Predictable promotions teach customers the real price. You are not creating demand so much as moving existing demand into your lowest-margin window, which is why full-price sell-through keeps eroding."},{id:"sal-12",mode:"standard",category:"sales",subskill:"channel saturation",industry:"Direct-to-consumer brand",difficulty:6,scenario:"One channel drove 80% of your growth for two years. Cost per acquisition there has risen 60% in six months while conversion, creative and landing pages are unchanged. Your team proposes a large creative refresh to bring costs back down.",prompt:"What is the most likely situation, and the right response?",choices:[{id:"a",text:"Creative fatigue; the refresh should restore prior efficiency"},{id:"b",text:"The reachable audience in that channel is saturating; test new channels while the current one still works"},{id:"c",text:"A tracking problem is inflating reported cost; audit the analytics"},{id:"d",text:"Competitors are outbidding you; increase bids to hold position"}],correctChoiceId:"b",explanation:"With conversion and creative performance unchanged, rising cost points to a thinning pool of remaining buyers rather than fatigue. A refresh may buy a few months; the durable move is to diversify before the channel stops funding it."}],c=[{id:"str-01",mode:"standard",category:"strategy",subskill:"where to compete",industry:"Independent bookstore",difficulty:1,scenario:"A national chain opened nearby and prices every title 25% below you. You cannot match their buying power.",prompt:"What is the sound strategic response?",choices:[{id:"a",text:"Match their prices to keep customers"},{id:"b",text:"Compete on something they cannot copy, such as curation, events and community"},{id:"c",text:"Cut staff to fund lower prices"},{id:"d",text:"Reduce hours to save money until they leave"}],correctChoiceId:"b",explanation:"Fighting on the one dimension where your opponent is structurally stronger is a losing plan. Strategy is choosing a field where your advantages count."},{id:"str-02",mode:"standard",category:"strategy",subskill:"concentration risk",industry:"Contract manufacturing",difficulty:1,scenario:"One customer is 70% of your revenue. They are happy, growing, and pay on time. Their contract renews annually.",prompt:"How should you think about this?",choices:[{id:"a",text:"It is fine as long as the relationship is healthy"},{id:"b",text:"It is a serious risk, and diversifying should start now while you are strong"},{id:"c",text:"You should raise their prices to capture more of the relationship"},{id:"d",text:"You should ask them to sign a longer contract and stop worrying"}],correctChoiceId:"b",explanation:"A single decision by someone outside your company could remove 70% of your revenue. The time to diversify is while you are healthy and have the leverage to be selective."},{id:"str-03",mode:"standard",category:"strategy",subskill:"focus over breadth",industry:"SaaS startup",difficulty:2,scenario:"Your product serves dentists, law firms and gyms. Dentists are 15% of customers, renew at 91%, and refer others. The other two segments renew at about 55% and demand constant custom work.",prompt:"What should you do?",choices:[{id:"a",text:"Build features for all three to broaden the market"},{id:"b",text:"Concentrate the product and go-to-market on dentists"},{id:"c",text:"Raise prices on the low-retention segments"},{id:"d",text:"Keep the mix; concentration is risky"}],correctChoiceId:"b",explanation:"One segment retains, refers and asks for less. Spreading a small team across three markets means being mediocre in all of them instead of dominant in the one that already works."},{id:"str-04",mode:"standard",category:"strategy",subskill:"deepen versus expand",industry:"Regional coffee chain",difficulty:2,scenario:"You have six stores in one metro. Same-store sales are growing 9% a year and all six are profitable. You could open three stores in a new city 200 miles away, or three more in your existing metro.",prompt:"Which is the lower-risk path to the same growth?",choices:[{id:"a",text:"The new city, to avoid competing with your own stores"},{id:"b",text:"The existing metro, where brand, supply and management already work"},{id:"c",text:"Split them, opening in both"},{id:"d",text:"Neither; grow only through existing stores"}],correctChoiceId:"b",explanation:"In your own metro you reuse brand awareness, supply routes and a management team that can physically visit. A distant city asks you to rebuild all three at once, which is a different and much larger bet."},{id:"str-05",mode:"standard",category:"strategy",subskill:"segment economics",industry:"Equipment rental",difficulty:3,scenario:"Trailing twelve months by customer segment:",data:{columns:["Segment","Revenue","Gross margin","Growth"],rows:[{label:"Large contractors",values:["$5.2M","22%","+3%"]},{label:"Small contractors",values:["$2.1M","41%","+28%"]},{label:"Homeowners",values:["$0.9M","38%","+2%"]}],note:"All three segments use the same fleet and branches."},prompt:"Where should the next investment go?",choices:[{id:"a",text:"Large contractors, the biggest revenue base"},{id:"b",text:"Small contractors"},{id:"c",text:"Homeowners, for brand visibility"},{id:"d",text:"Spread investment proportionally to current revenue"}],correctChoiceId:"b",explanation:"Small contractors combine the highest margin with by far the fastest growth on shared assets. The largest segment is the least profitable and barely moving."},{id:"str-06",mode:"standard",category:"strategy",subskill:"durable advantage",industry:"Consumer app",difficulty:3,scenario:"Your best-performing feature was copied by a larger competitor within seven weeks of launch. Your team wants to build the next feature faster to stay ahead.",prompt:"What is the better strategic question?",choices:[{id:"a",text:"How do we ship features faster than they can copy them?"},{id:"b",text:"What advantage do we have that copying a feature does not transfer?"},{id:"c",text:"Should we patent our features?"},{id:"d",text:"How do we price below them to hold users?"}],correctChoiceId:"b",explanation:"A feature race against a bigger company is a race you lose on resources. Advantages that survive copying — data, network effects, distribution, switching costs, brand — are what a strategy has to be built on."},{id:"str-07",mode:"standard",category:"strategy",subskill:"build versus buy",industry:"E-commerce",difficulty:4,scenario:"Third-party fulfillment costs you $6.40 per order at 40,000 orders a month. Your own warehouse would cost $1.9M up front and about $4.10 per order, and would take a year to reach full efficiency. Your order volume has swung between 22,000 and 55,000 a month over the past year.",prompt:"What matters most in this decision?",choices:[{id:"a",text:"The $2.30 per order saving, worth about $1.1M a year at current volume"},{id:"b",text:"Whether your volume floor is high enough to carry the fixed cost in a bad year"},{id:"c",text:"Whether owning fulfillment improves delivery speed"},{id:"d",text:"Whether you can raise the $1.9M"}],correctChoiceId:"b",explanation:"Converting variable cost into fixed cost is a bet on your worst month, not your average one. At 22,000 orders the same fixed base has to be absorbed by far fewer units, which is where this decision is actually decided."},{id:"str-08",mode:"standard",category:"strategy",subskill:"sequencing expansion",industry:"Restaurant",difficulty:4,scenario:"Your single location does $2.4M a year with 9% net margin, and you personally solve problems most days. An investor offers to fund three more locations immediately on attractive terms.",prompt:"What should you weigh most heavily?",choices:[{id:"a",text:"Whether the terms are the best you will be offered"},{id:"b",text:"Whether the business runs well without you in the building"},{id:"c",text:"Whether the new sites have enough foot traffic"},{id:"d",text:"Whether 9% margin is strong enough for the category"}],correctChoiceId:"b",explanation:"Multi-unit operations replicate a system, not a person. If the current location depends on you being there daily, three more locations produce four struggling restaurants rather than four times the profit."},{id:"str-09",mode:"standard",category:"strategy",subskill:"commoditization",industry:"IT hardware reseller",difficulty:5,scenario:"Hardware margins have fallen from 18% to 6% over four years as buyers compare prices online. Your customers still call you for configuration advice, migration planning and support, which you provide free to win the hardware sale.",prompt:"What is the strategic move?",choices:[{id:"a",text:"Cut costs to stay profitable at 6% margin"},{id:"b",text:"Charge for the services and treat hardware as the low-margin attachment"},{id:"c",text:"Add more product lines to increase volume"},{id:"d",text:"Exit hardware entirely and become a pure consultancy"}],correctChoiceId:"b",explanation:"The commoditized part is the box; the scarce part is the judgment you give away. Repricing around what customers actually cannot get elsewhere is what stops the margin slide."},{id:"str-10",mode:"standard",category:"strategy",subskill:"sunk cost",industry:"Software company",difficulty:5,scenario:"You have spent $1.8M and two years on a product. It has 40 customers, growth is flat, and finishing the roadmap would cost another $900,000. The same $900,000 spent on your profitable core product is expected to return roughly $2.5M.",prompt:"What should you do?",choices:[{id:"a",text:"Finish the product; abandoning it wastes the $1.8M already invested"},{id:"b",text:"Put the $900,000 into the core product"},{id:"c",text:"Split the money between both"},{id:"d",text:"Sell the new product line at any price to recover the investment"}],correctChoiceId:"b",explanation:"The $1.8M is gone regardless of what you choose next. The only live question is where the next $900,000 earns most, and the core product is expected to return nearly three times the money."},{id:"str-11",mode:"standard",category:"strategy",subskill:"second-order effects",industry:"Marketplace platform",difficulty:6,scenario:"Raising your take rate from 12% to 18% would add roughly $9M of revenue next year with no immediate change in volume. Your largest sellers, who account for 55% of transactions, have publicly complained about fees and two competing marketplaces charge 10%.",prompt:"What is the central risk?",choices:[{id:"a",text:"Buyers will notice higher prices and shop elsewhere"},{id:"b",text:"The sellers who make the marketplace worth visiting have somewhere else to go"},{id:"c",text:"The revenue increase will attract regulatory attention"},{id:"d",text:"Support costs will rise with seller complaints"}],correctChoiceId:"b",explanation:"A marketplace is only valuable because of its supply. The $9M is immediate and visible; the loss of concentrated sellers to a cheaper rival is delayed, gradual, and much harder to reverse once buyers follow them."},{id:"str-12",mode:"standard",category:"strategy",subskill:"bounded bets under uncertainty",industry:"Consumer goods",difficulty:6,scenario:"Your team is split on entering a new category. Optimists project $12M in three years; skeptics expect losses. Entry requires $4M and a dedicated team, no one has spoken with target buyers, and the projections rest on a single analyst report.",prompt:"What is the best decision?",choices:[{id:"a",text:"Commit the $4M; hesitation cedes the category to competitors"},{id:"b",text:"Decline; the disagreement shows the team lacks conviction"},{id:"c",text:"Fund a small bounded test that produces real evidence before the full commitment"},{id:"d",text:"Commission a second analyst report to settle the disagreement"}],correctChoiceId:"c",explanation:"The disagreement is about facts nobody has gathered, and no report substitutes for contact with actual buyers. Spending a small fraction to convert the biggest unknown into evidence is what makes the $4M decision knowable."}],l=[{id:"day-01",mode:"daily",category:"bottleneck",subskill:"capacity versus demand",industry:"Craft brewery",difficulty:3,scenario:"Your taproom is full every weekend and distribution accounts are asking for more kegs than you can supply. Fermentation tanks run at 100% and a new tank takes four months to install. A distributor offers to double your account count starting next month.",prompt:"What should you do?",choices:[{id:"a",text:"Accept the expansion and stretch supply across more accounts"},{id:"b",text:"Decline for now and order tank capacity"},{id:"c",text:"Accept, and reduce taproom hours to free up kegs"},{id:"d",text:"Raise keg prices to ration demand across both channels"}],correctChoiceId:"b",explanation:"Doubling accounts you cannot supply turns one happy channel into two disappointed ones. Capacity has a four-month lead time, so ordering it is the move that makes the expansion possible later.",distribution:{a:21,b:54,c:9,d:16}},{id:"day-02",mode:"daily",category:"financial",subskill:"margin versus volume",industry:"Catering",difficulty:3,scenario:"A corporate client offers a recurring contract worth $180,000 a year — roughly 30% of your revenue — at a price that produces 9% gross margin. Your current book averages 34% gross margin and your kitchen is at 70% capacity.",prompt:"What is the strongest response?",choices:[{id:"a",text:"Take it; 30% more revenue and you have idle capacity"},{id:"b",text:"Decline; 9% margin is below what the business needs"},{id:"c",text:"Counter at a price closer to your normal margin, and be willing to walk"},{id:"d",text:"Take it and raise prices on your existing clients to compensate"}],correctChoiceId:"c",explanation:"Idle capacity makes a lower-margin job worth considering, but 30% of revenue at 9% margin reshapes the whole business and anchors your price with a reference customer. Negotiating first costs nothing and keeps both outcomes available.",distribution:{a:24,b:18,c:49,d:9}},{id:"day-03",mode:"daily",category:"sales",subskill:"funnel diagnosis",industry:"Gym franchise",difficulty:4,scenario:"Trial signups are up 45% after a new ad campaign. Trial-to-paid conversion fell from 38% to 19%. Total new members are roughly flat, and the sales team says the new leads are 'tire kickers'.",prompt:"What should you do first?",choices:[{id:"a",text:"Cut the campaign and return to the previous ad mix"},{id:"b",text:"Retrain the sales team on converting trials"},{id:"c",text:"Compare the two lead groups before changing anything"},{id:"d",text:"Add a paid trial to filter out low-intent signups"}],correctChoiceId:"c",explanation:"Two explanations fit equally well: worse leads, or a team overwhelmed by 45% more of them. The data to tell them apart already exists, and each explanation has a completely different fix.",distribution:{a:17,b:14,c:46,d:23}},{id:"day-04",mode:"daily",category:"people",subskill:"delegation",industry:"Architecture firm",difficulty:3,scenario:"You review every drawing before it leaves the office. Reviews now take 11 days on average, clients are complaining, and you catch a meaningful error in roughly 1 of 20 sets.",prompt:"What is the best change?",choices:[{id:"a",text:"Keep reviewing everything but work through them faster"},{id:"b",text:"Have senior staff review, with you sampling and coaching on what they miss"},{id:"c",text:"Stop reviewing and rely on the team"},{id:"d",text:"Hire a second principal to split the review load"}],correctChoiceId:"b",explanation:"The 11-day delay costs more than the 1-in-20 catch rate justifies, but dropping review entirely throws away the quality signal. Distributing the review and sampling it keeps the catch rate while removing you as the queue.",distribution:{a:8,b:61,c:7,d:24}},{id:"day-05",mode:"daily",category:"strategy",subskill:"customer concentration",industry:"Packaging supplier",difficulty:4,scenario:"Your largest customer, 45% of revenue, asks for a 12% price reduction and hints they are getting competing quotes. Matching it would take your net margin from 11% to about 4%. You have capacity to serve others but no active pipeline.",prompt:"What is the best move?",choices:[{id:"a",text:"Match the price to protect the relationship"},{id:"b",text:"Refuse and let them go if necessary"},{id:"c",text:"Offer a smaller reduction tied to volume or longer terms, and start building pipeline immediately"},{id:"d",text:"Match the price and cut costs to restore margin"}],correctChoiceId:"c",explanation:"You are negotiating from a weak position because you have no alternatives, and that is the thing you can actually change. Trading price for commitment buys margin and time; building pipeline fixes the underlying vulnerability either way.",distribution:{a:26,b:11,c:51,d:12}},{id:"day-06",mode:"daily",category:"operations",subskill:"quality economics",industry:"Cosmetics manufacturing",difficulty:4,scenario:"Customer returns run at 4% and cost about $340,000 a year. Nearly all of them trace to one filling machine that runs slightly out of tolerance. Replacing it costs $500,000 and takes the line down for two weeks, worth about $220,000 of lost output.",prompt:"How should you evaluate this?",choices:[{id:"a",text:"Reject it; $720,000 of cost to save $340,000 a year"},{id:"b",text:"Approve it; it pays back in roughly two years and removes a recurring problem"},{id:"c",text:"Approve only if returns exceed 6%"},{id:"d",text:"Keep the machine and add inspection to catch defects before shipping"}],correctChoiceId:"b",explanation:"The $220,000 of downtime is one-time while the $340,000 is annual, so total outlay is recovered in a bit over two years and every year after is profit. Inspection would add permanent cost without removing the defect.",distribution:{a:19,b:47,c:10,d:24}},{id:"day-07",mode:"daily",category:"prioritization",subskill:"opportunity cost",industry:"Boutique fitness",difficulty:3,scenario:"You can do exactly one thing this quarter: open a second studio, launch an at-home digital product, or fix the scheduling and retention problems that cost you an estimated 15% of members a year.",prompt:"What should you choose?",choices:[{id:"a",text:"Open the second studio while the market is good"},{id:"b",text:"Launch the digital product for a new revenue stream"},{id:"c",text:"Fix scheduling and retention"},{id:"d",text:"Attempt the studio and the digital product together"}],correctChoiceId:"c",explanation:"A 15% annual leak devalues every member you will ever acquire, in this studio and any future one. Expanding first copies the leak into a second location.",distribution:{a:22,b:12,c:58,d:8}},{id:"day-08",mode:"daily",category:"resource",subskill:"capital allocation",industry:"Dental group",difficulty:4,scenario:"You have $250,000. Option A buys a same-day crown mill that eliminates a lab fee worth $190,000 a year but requires training your two busiest dentists. Option B adds two operatories, and your schedule is currently booked 4 weeks out with 12% of callers going unserved.",prompt:"Which is stronger, and why?",choices:[{id:"a",text:"The crown mill, because $190,000 a year is a certain, immediate saving"},{id:"b",text:"The operatories, because unserved demand is revenue you are losing today"},{id:"c",text:"Neither until you know how much of the 12% is recoverable and what the mill does to chair time"},{id:"d",text:"Split the budget across both"}],correctChoiceId:"c",explanation:"Both look strong and they interact: the mill consumes chair time from the same dentists whose capacity option B is trying to expand. Two cheap questions decide a $250,000 commitment.",distribution:{a:27,b:31,c:34,d:8}},{id:"day-09",mode:"daily",category:"financial",subskill:"cash versus profit",industry:"Landscaping",difficulty:3,scenario:"You won a $400,000 municipal contract, your largest ever. It requires $120,000 of materials and equipment up front, pays 60 days after completion, and the work takes four months. Your operating account holds $85,000 and your credit line is maxed.",prompt:"What should you do?",choices:[{id:"a",text:"Take it; a contract this size will fix the cash position"},{id:"b",text:"Take it only after securing financing or a mobilization payment"},{id:"c",text:"Decline it; the business is too small for this contract"},{id:"d",text:"Take it and delay supplier payments to bridge the gap"}],correctChoiceId:"b",explanation:"The contract is profitable but you cannot fund it — $120,000 out against $85,000 available, with cash six months away. Winning work you cannot finance is one of the most common ways profitable companies fail.",distribution:{a:15,b:63,c:9,d:13}},{id:"day-10",mode:"daily",category:"operations",subskill:"process versus people",industry:"Urgent care",difficulty:4,scenario:"Patient wait times average 52 minutes against a 30-minute target. Staffing matches patient volume hour by hour. About 35% of visit time is spent on registration and insurance verification, which happens after the patient arrives.",prompt:"What is the highest-leverage change?",choices:[{id:"a",text:"Add a provider during peak hours"},{id:"b",text:"Move registration and verification before arrival"},{id:"c",text:"Set a wait-time target for staff and track it"},{id:"d",text:"Extend hours to spread demand"}],correctChoiceId:"b",explanation:"Staffing already matches volume, so more people will not compress a process that spends a third of its time on paperwork. Moving that work before arrival removes it from the patient's clock entirely.",distribution:{a:29,b:52,c:6,d:13}},{id:"day-11",mode:"daily",category:"strategy",subskill:"second-order effects",industry:"Software",difficulty:5,scenario:"Your free tier accounts for 88% of users and 0% of revenue, and costs about $40,000 a month to serve. Roughly 40% of paid customers say they first tried the free tier, and a third of new paid accounts arrive through free-user referrals.",prompt:"What should you do?",choices:[{id:"a",text:"Eliminate the free tier and save $480,000 a year"},{id:"b",text:"Keep it, but measure and manage it as an acquisition channel"},{id:"c",text:"Keep it exactly as it is; it clearly works"},{id:"d",text:"Convert it to a 14-day trial to force decisions"}],correctChoiceId:"b",explanation:"The free tier is not a cost centre, it is your largest acquisition channel wearing a cost centre's clothes. Once you judge it on cost per paid customer you can optimize it honestly rather than kill it or protect it on faith.",distribution:{a:14,b:55,c:12,d:19}},{id:"day-12",mode:"daily",category:"people",subskill:"incentives and behavior",industry:"Staffing agency",difficulty:4,scenario:"Recruiters are paid on placements made. Placement volume is up 30% this year. Your 90-day retention of placed candidates fell from 84% to 62%, and three clients have stopped sending requisitions.",prompt:"What is the correct read?",choices:[{id:"a",text:"Recruiters are placing candidates who should not be placed"},{id:"b",text:"Client expectations have become unrealistic"},{id:"c",text:"The labour market has become less stable"},{id:"d",text:"Recruiters need better interview training"}],correctChoiceId:"a",explanation:"You pay for placements, so you get placements. Volume up and retention down together is the classic signature of an incentive rewarding the transaction rather than the outcome the client is buying.",distribution:{a:57,b:13,c:18,d:12}},{id:"day-13",mode:"daily",category:"prioritization",subskill:"signal versus noise",industry:"Grocery chain",difficulty:4,scenario:"Same-store sales are flat. Your loudest store manager insists the issue is a competitor's new location. Basket size is up 4%, transaction count is down 6%, and loyalty members are visiting 1.8 times a month instead of 2.1.",prompt:"What does the data point to?",choices:[{id:"a",text:"The competitor is taking customers, as the manager says"},{id:"b",text:"A visit-frequency problem among customers you still have"},{id:"c",text:"A pricing problem, since basket size rose"},{id:"d",text:"Nothing conclusive; flat sales are within normal variation"}],correctChoiceId:"b",explanation:"Your known customers are still shopping with you, just less often, and they spend more when they come. That is a frequency problem, which has different remedies than losing customers outright.",distribution:{a:33,b:44,c:11,d:12}},{id:"day-14",mode:"daily",category:"bottleneck",subskill:"constraint identification",industry:"Boutique winery",difficulty:3,scenario:"Tasting room visits are up 30%. Wine club signups, your most profitable channel, are flat. Staff say they rarely have time to explain the club because they are pouring for a full bar, and the room is at capacity most afternoons.",prompt:"What should you change?",choices:[{id:"a",text:"Increase marketing to drive more tasting room visits"},{id:"b",text:"Create dedicated staff or space for club conversations"},{id:"c",text:"Raise tasting fees to reduce crowding"},{id:"d",text:"Offer a club discount to improve the conversion rate"}],correctChoiceId:"b",explanation:"The visits are already there; the conversion step has no capacity. More traffic makes the crowding worse, and a discount cannot be offered by someone who has no time to make the offer.",distribution:{a:12,b:59,c:8,d:21}}];var h=e.i(73109);let u=[...o,...s,...n,...i,...d,...a,...r,...c],p={standard:u.length,quick:h.QUICK_QUESTIONS.length,daily:l.length};e.s(["BANK_STATS",0,p,"QUESTION_BANK",0,u,"dailyQuestionFor",0,function(e){let o=(0,t.hashString)(e)%l.length;return l[o]},"findQuestion",0,function(e){return u.find(t=>t.id===e)},"questionsForCategory",0,function(e){return u.filter(t=>t.category===e)}],94467)}]);